config_source=b'"""One root-only read-only capture of fixed current configuration digests.\n\nThe path inventory is historical104 source. No historical digest is reused.\nThis fresh preservation baseline supplies no execution/activation authority.\nNo configuration contents or included-file instructions are emitted/interpreted.\n"""\nimport datetime,hashlib,json,os,resource,signal,socket,stat,sys,time\nfrom pathlib import Path\n\nPATHS=(\'/etc/dovecot/dovecot.conf\', \'/etc/dovecot/conf.d/10-auth.conf\', \'/etc/dovecot/conf.d/10-director.conf\', \'/etc/dovecot/conf.d/10-logging.conf\', \'/etc/dovecot/conf.d/10-mail.conf\', \'/etc/dovecot/conf.d/10-master.conf\', \'/etc/dovecot/conf.d/10-metrics.conf\', \'/etc/dovecot/conf.d/10-ssl.conf\', \'/etc/dovecot/conf.d/15-lda.conf\', \'/etc/dovecot/conf.d/15-mailboxes.conf\', \'/etc/dovecot/conf.d/20-imap.conf\', \'/etc/dovecot/conf.d/20-lmtp.conf\', \'/etc/dovecot/conf.d/20-managesieve.conf\', \'/etc/dovecot/conf.d/20-pop3.conf\', \'/etc/dovecot/conf.d/20-submission.conf\', \'/etc/dovecot/conf.d/90-acl.conf\', \'/etc/dovecot/conf.d/90-plugin.conf\', \'/etc/dovecot/conf.d/90-quota.conf\', \'/etc/dovecot/conf.d/90-sieve-extprograms.conf\', \'/etc/dovecot/conf.d/90-sieve.conf\', \'/etc/dovecot/conf.d/99-bbs-imaps-only.conf\', \'/etc/dovecot/conf.d/99-bbs-managesieve-policy.conf\', \'/etc/dovecot/conf.d/99-rspamd-warning-labels.conf\', \'/etc/dovecot/local.conf\', \'/etc/dovecot/conf.d/auth-sql.conf.ext\')\nKNOWN_ABSENT=(\'/etc/dovecot/conf.d/99-bbs-imaps-only.conf\', \'/etc/dovecot/conf.d/99-bbs-managesieve-policy.conf\')\nSQL=\'/etc/dovecot/dovecot-sql.conf.ext\'\nDIRECTORIES=(\'/usr/local/libexec/osmap\',\'/var\',\'/var/db\',\'/var/db/osmap-account\')\nSTART=time.monotonic();END=START+30\nclass Refused(Exception):pass\ndef require(value,code):\n    if not value:raise Refused(code)\ndef before():require(time.monotonic()<END,\'WHOLE_DEADLINE\')\ndef identity(m):return(m.st_dev,m.st_ino,m.st_uid,m.st_gid,m.st_mode,m.st_nlink,m.st_size,m.st_mtime_ns,m.st_ctime_ns)\ndef protected_ancestors(path):\n    found=[]\n    for parent in path.parents:\n        before();m=parent.lstat()\n        require(stat.S_ISDIR(m.st_mode)and m.st_uid==0 and not m.st_mode&0o022,\'ANCESTOR_CUSTODY\')\n        found.append((parent,identity(m)))\n    return found\ndef current_ancestors(ancestors):\n    for path,prior in ancestors:\n        # Sibling activity changes directory size/link count/times, not custody.\n        before();require(identity(path.lstat())[:5]==prior[:5],\'ANCESTOR_CHANGED\')\ndef current_hash(name):\n    path=Path(name);before();ancestors=protected_ancestors(path);m=path.lstat();prior=identity(m)\n    require(stat.S_ISREG(m.st_mode)and m.st_uid==0 and m.st_nlink==1 and not m.st_mode&0o022 and 0<=m.st_size<=131072,\'FILE_CUSTODY\')\n    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK|os.O_CLOEXEC)\n    try:\n        require(identity(os.fstat(fd))==prior,\'OPEN_CHANGED\');digest=hashlib.sha256();count=0\n        while True:\n            before();part=os.read(fd,min(16384,131073-count))\n            if not part:break\n            count+=len(part);require(count<=131072,\'FILE_BOUND\');digest.update(part)\n        before();require(count==m.st_size and identity(os.fstat(fd))==prior and identity(path.lstat())==prior,\'FILE_CHANGED\')\n        current_ancestors(ancestors)\n        return digest.hexdigest(),prior,ancestors\n    finally:os.close(fd)\ndef capture_fixed(name):\n    try:return current_hash(name)\n    except FileNotFoundError:\n        require(name in KNOWN_ABSENT,\'REQUIRED_CONFIG_MISSING\')\n        path=Path(name);ancestors=protected_ancestors(path)\n        require(not os.path.lexists(path),\'ABSENT_CONFIG_PRESENT\')\n        current_ancestors(ancestors)\n        return None,None,ancestors\ndef directory_metadata(name):\n    path=Path(name);before()\n    try:\n        ancestors=protected_ancestors(path);m=path.lstat()\n        require(stat.S_ISDIR(m.st_mode)and m.st_uid==0 and not m.st_mode&0o022,\'DIRECTORY_CUSTODY\')\n        current_ancestors(ancestors)\n        return {\'status\':\'OBSERVED\',\'metadata\':list(identity(m))}\n    except FileNotFoundError:return {\'status\':\'MISSING\'}\n    except PermissionError:return {\'status\':\'INACCESSIBLE\'}\n    except Refused as e:\n        if str(e)in(\'INTERRUPTED\',\'WHOLE_DEADLINE\'):raise\n        return {\'status\':str(e)}\ndef interrupted(_number,_frame):raise Refused(\'INTERRUPTED\')\ndef main():\n    out={\'schema\':\'osmap-single-host-current-config-map-v1\',\'observed_at\':datetime.datetime.now(datetime.timezone.utc).isoformat(),\'result\':\'REFUSED\',\'fixed_config_count\':25,\'config_map\':None,\'public_sql_sha256\':None,\'files\':{},\'directories\':{},\'host_file_writes\':False,\'public_service_operations\':False,\'database_operations\':False,\'credential_operations\':False,\'contents_retained\':False,\'historical_hash_values_reused\':False}\n    try:\n        resource.setrlimit(resource.RLIMIT_CORE,(0,0));os.chdir(\'/\')\n        for number in(signal.SIGALRM,signal.SIGHUP,signal.SIGTERM,signal.SIGINT):signal.signal(number,interrupted)\n        signal.alarm(30)\n        u=os.uname();out[\'identity\']={\'hostname\':socket.gethostname(),\'system\':u.sysname,\'release\':u.release,\'machine\':u.machine,\'uid\':os.getuid(),\'euid\':os.geteuid(),\'gid\':os.getgid(),\'egid\':os.getegid()}\n        require(len(sys.argv)==1,\'ARGUMENTS_REFUSED\')\n        require((out[\'identity\'][\'hostname\'],u.sysname,u.machine,os.getuid(),os.geteuid(),os.getgid(),os.getegid())==(\'obsd1.blackbagsecurity.com\',\'OpenBSD\',\'amd64\',0,0,0,0),\'ROOT_TARGET_REFUSED\')\n        captured={}\n        for name in (*PATHS,SQL):\n            try:\n                captured[name]=capture_fixed(name);out[\'files\'][name]={\'status\':\'PRESERVED_ABSENT\'if captured[name][0]is None else\'CUSTODY_PASS\',\'metadata\':None if captured[name][1]is None else list(captured[name][1])}\n            except FileNotFoundError:out[\'files\'][name]={\'status\':\'MISSING\'}\n            except PermissionError:out[\'files\'][name]={\'status\':\'INACCESSIBLE\'}\n            except Refused as e:\n                if str(e)in(\'INTERRUPTED\',\'WHOLE_DEADLINE\'):raise\n                out[\'files\'][name]={\'status\':str(e)}\n        out[\'directories\']={name:directory_metadata(name)for name in DIRECTORIES}\n        require(len(captured)==26,\'CONFIG_SET_INCOMPLETE\')\n        # One final metadata/ancestor reconciliation prevents emitting a mixed\n        # preservation map after an earlier captured leaf/namespace changed.\n        for name,(_digest,prior,ancestors)in captured.items():\n            before()\n            if prior is None:require(name in KNOWN_ABSENT and not os.path.lexists(name),\'FINAL_ABSENT_CONFIG_CREATED\')\n            else:require(identity(Path(name).lstat())==prior,\'FINAL_FILE_CHANGED\')\n            current_ancestors(ancestors)\n        before();out[\'absent_paths\']=[name for name in PATHS if captured[name][0]is None];out[\'config_map\']={name:captured[name][0]for name in PATHS};out[\'public_sql_sha256\']=captured[SQL][0];out[\'result\']=\'CAPTURE_PASS\'\n    except Refused as e:out[\'failure\']=str(e)\n    except OSError:out[\'failure\']=\'OBSERVATION_UNAVAILABLE\'\n    except Exception:out[\'failure\']=\'UNEXPECTED_OBSERVATION_REFUSAL\'\n    finally:signal.alarm(0)\n    if out[\'result\']!=\'CAPTURE_PASS\':out[\'config_map\']=None;out[\'public_sql_sha256\']=None\n    out[\'elapsed_millis\']=int((time.monotonic()-START)*1000);print(json.dumps(out,sort_keys=True));return 0 if out[\'result\']==\'CAPTURE_PASS\'else 1\nif __name__==\'__main__\':raise SystemExit(main())\n'
